#define main legacy_main
#include "../spaxpby-cuda/main.cu"
#undef main
#include <vector>
#include <algorithm>
#include <string>
#include <dlfcn.h>
#define CU(x) do{if((x)!=cudaSuccess)abort();}while(0)
#define SP(x) do{if((x)!=CUSPARSE_STATUS_SUCCESS)abort();}while(0)
struct F{std::vector<int64_t>idx;std::vector<float>x,y,gold;float a,b;int64_t*di;float *dx,*dy;cusparseSpVecDescr_t sx;cusparseDnVecDescr_t sy;F(int f,int rep){int n=4099,k=f==0?1027:f==1?4099:7;a=f==0?1:f==1?-.5:2;b=f==0?1:f==1?.5:0;for(int j=0;j<k;j++)idx.push_back((37*j+11)%n);std::sort(idx.begin(),idx.end());for(auto i:idx)x.push_back(float(i%17-8)/16);for(int i=0;i<n;i++)y.push_back(float(i%23-11)/8);gold=y;std::vector<double>dense(n);for(int j=0;j<k;j++)dense[idx[j]]=x[j];for(int z=0;z<rep;z++){for(float&v:gold)v=float(double(b)*double(v));for(auto i:idx)gold[i]=float(double(gold[i])+double(a)*dense[i]);}CU(cudaMalloc(&di,k*8));CU(cudaMalloc(&dx,k*4));CU(cudaMalloc(&dy,n*4));CU(cudaMemcpy(di,idx.data(),k*8,cudaMemcpyHostToDevice));CU(cudaMemcpy(dx,x.data(),k*4,cudaMemcpyHostToDevice));CU(cudaMemcpy(dy,y.data(),n*4,cudaMemcpyHostToDevice));SP(cusparseCreateSpVec(&sx,n,k,di,dx,CUSPARSE_INDEX_64I,CUSPARSE_INDEX_BASE_ZERO,CUDA_R_32F));SP(cusparseCreateDnVec(&sy,n,dy,CUDA_R_32F));}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;cusparseHandle_t h;SP(cusparseCreate(&h));int version;SP(cusparseGetVersion(h,&version));Dl_info info;dladdr((void*)cusparseGetVersion,&info);printf("VENDOR_CUSPARSE version=%d path=%s\n",version,info.dli_fname);std::vector<F>fs;std::vector<float>prefix;for(int f=0;f<3;f++){fs.emplace_back(f,rep);auto&q=fs.back();prefix.insert(prefix.end(),{float(q.y.size()),float(q.x.size()),q.a,q.b});for(auto i:q.idx)prefix.push_back(float(i));prefix.insert(prefix.end(),q.x.begin(),q.x.end());prefix.insert(prefix.end(),q.y.begin(),q.y.end());SP(cusparseAxpby(h,&q.a,q.sx,&q.b,q.sy));}CU(cudaDeviceSynchronize());for(int trial=1;trial<=5;trial++){for(auto&q:fs)CU(cudaMemcpy(q.dy,q.y.data(),q.y.size()*4,cudaMemcpyHostToDevice));CU(cudaDeviceSynchronize());auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)for(auto&q:fs)SP(cusparseAxpby(h,&q.a,q.sx,&q.b,q.sy));CU(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;std::vector<float>got;double err=0;bool ok=true;for(auto&q:fs){std::vector<float>v(q.y.size());CU(cudaMemcpy(v.data(),q.dy,v.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<v.size();i++){ok&=std::isfinite(v[i]);err=std::max(err,fabs(double(v[i])-q.gold[i]));}got.insert(got.end(),v.begin(),v.end());}ok&=err<=1e-6;auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"three_sparse_axpby_recurrences_host_dispatch_sync_excludes_reset\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),err,rep,path.c_str(),art.size());if(!ok)return 2;}for(auto&q:fs){cusparseDestroySpVec(q.sx);cusparseDestroyDnVec(q.sy);cudaFree(q.di);cudaFree(q.dx);cudaFree(q.dy);}cusparseDestroy(h);}
